const UNITS = { h: 3600000, m: 60000, s: 1000, ms: 1 };

export function parseDuration(text) {
  const str = String(text);
  if (str.length === 0) throw new Error(`bad duration: ${text}`);

  const re = /(\d+)(ms|h|m|s)/g;
  let total = 0;
  let pos = 0;
  let m;

  while ((m = re.exec(str)) !== null) {
    if (m.index !== pos) throw new Error(`bad duration: ${text}`);
    total += Number(m[1]) * UNITS[m[2]];
    pos = re.lastIndex;
  }

  if (pos !== str.length) throw new Error(`bad duration: ${text}`);
  return total;
}

