import { test } from 'node:test';
import assert from 'node:assert/strict';
import { deepMerge } from '../src/merge.js';

test('nested', () => {
  assert.deepEqual(deepMerge({ a: { x: 1 } }, { a: { y: 2 } }), { a: { x: 1, y: 2 } });
});

test('does not mutate inputs', () => {
  const base = { a: { x: 1 } };
  const override = { a: { y: 2 } };
  deepMerge(base, override);
  assert.deepEqual(base, { a: { x: 1 } });
  assert.deepEqual(override, { a: { y: 2 } });
});

test('arrays replace instead of merging', () => {
  assert.deepEqual(deepMerge({ a: [1, 2] }, { a: [3] }), { a: [3] });
});

test('primitives replace', () => {
  assert.deepEqual(deepMerge({ a: 1, b: 'hello' }, { a: 2, b: 'world' }), { a: 2, b: 'world' });
});

test('nested plain objects merge recursively', () => {
  assert.deepEqual(
    deepMerge({ a: { b: { c: 1 }, d: 2 } }, { a: { b: { e: 3 } } }),
    { a: { b: { c: 1, e: 3 }, d: 2 } }
  );
});

